        anomaly_dates = self.data[anomaly_mask].index
        anomaly_prices = self.data[anomaly_mask]['Close']

        ax1.scatter(anomaly_dates, anomaly_prices, color='red', s=100, 
                   label=f'Anomalies (|Z| > {self.z_threshold})', zorder=5)

        ax1.set_title(f'{self.ticker} Stock Price - Last {self.days} Trading Days', fontsize=14, fontweight='bold')
        ax1.set_ylabel('Price ($)', fontsize=12)
        ax1.legend()
        ax1.grid(True, alpha=0.3)

        # Format x-axis dates
        ax1.xaxis.set_major_formatter(mdates.DateFormatter('%m/%d'))
        ax1.xaxis.set_major_locator(mdates.DayLocator(interval=2))

        # Plot 2: Daily returns with Z-score threshold lines
        returns_pct = self.data['Daily_Return'] * 100  # Convert to percentage

        ax2.bar(dates[1:], returns_pct[1:], alpha=0.7, 
               color=['red' if abs(z) > self.z_threshold else 'blue' 
                     for z in self.data['Z_Score'][1:]])

        # Add threshold lines
        ax2.axhline(y=0, color='black', linestyle='-', alpha=0.5)

        ax2.set_title('Daily Returns with Anomaly Detection', fontsize=14, fontweight='bold')
        ax2.set_ylabel('Daily Return (%)', fontsize=12)
        ax2.set_xlabel('Date', fontsize=12)
        ax2.grid(True, alpha=0.3)

        # Format x-axis dates
        ax2.xaxis.set_major_formatter(mdates.DateFormatter('%m/%d'))
        ax2.xaxis.set_major_locator(mdates.DayLocator(interval=2))

        plt.tight_layout()
        plt.xticks(rotation=45)
        plt.savefig(filename, dpi=300, bbox_inches='tight')
        plt.close()

        print(f"Chart saved as {filename}")

    def generate_json_report(self, filename: str = 'anomaly_report.json') -> None:
        """Generate and save a JSON report with anomaly details."""
        if self.data is None:
            raise ValueError("No data available for report generation")

        # Calculate summary statistics
        returns = self.data['Daily_Return'].dropna()

        report = {
            'analysis_metadata': {
                'ticker': self.ticker,
                'analysis_date': datetime.now().isoformat(),
                'period_days': self.days,
                'z_threshold': self.z_threshold,
                'trading_days_analyzed': len(self.data)
            },
            'summary_statistics': {
                'mean_daily_return': float(round(returns.mean() * 100, 4)),
                'std_daily_return': float(round(returns.std() * 100, 4)),
                'min_daily_return': float(round(returns.min() * 100, 2)),
                'max_daily_return': float(round(returns.max() * 100, 2)),
                'total_anomalies_detected': len(self.anomalies)
            },
            'anomalous_days': self.anomalies,
            'all_trading_days': []
        }

        # Add all trading days data
        for date, row in self.data.iterrows():
            if pd.notna(row['Daily_Return']):
                day_data = {
                    'date': date.strftime('%Y-%m-%d'),
                    'close_price': float(round(row['Close'], 2)),
                    'daily_return': float(round(row['Daily_Return'] * 100, 2)),
                    'z_score': float(round(row['Z_Score'], 3)),
                    'volume': int(row['Volume']),
                    'is_anomaly': bool(abs(row['Z_Score']) > self.z_threshold)
                }
                report['all_trading_days'].append(day_data)

        with open(filename, 'w') as f:
            json.dump(report, f, indent=2)

        print(f"JSON report saved as {filename}")

